(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["bg"] = {"ui":{"skip":"Към съдържанието","back":"← Обратно към AI-gile","lang.button":"Език: {name}","lang.dialog":"Избери език","lang.search":"Търси език","lang.none":"Няма съвпадащ език","lang.notYet":"{name} още не е преведен","theme.aria":"Смяна на темата: светла, тъмна или черна","theme.toLight":"Към светла тема","theme.toDark":"Към тъмна тема","theme.toBlack":"Към черна тема (истинско черно, щадящо OLED екраните)","words.underline":"Подчертай тези думи на страницата","words.underlineHelp":"Посочи или докосни дума с точки отдолу, за да видиш какво означава.","words.col.todo":"Избрани за момента карти: екипът започва с тях след това.","words.col.doing":"Един AI работи по тази карта в момента.","words.col.review":"Един AI е свършил работата; друг я проверява, преди да стигне до теб.","words.col.verify":"Чака теб: пробвай го и кажи дали работи.","words.col.team":"Твоите бележки или отговори, които чакат екипът да ги поеме.","words.col.done":"Завършено и прието.","index.title":"AI-gile: твоят AI екип за разработка, на една дъска","index.description":"AI-gile е канбан дъска за екипи, които кодират с изкуствен интелект. Те работят, докато спиш; ти получаваш една кратка купчинка неща за решаване, тестване и приемане.","hero.logoAlt":"Икона на дъската на AI-gile","hero.h1.html":"Твоят AI екип за разработка, на една&nbsp;дъска.","hero.alpha":"🐣 Затворена пре-алфа","hero.alphaTitle":"Рано и недовършено: благодаря, че го пробваш!","hero.lede":"Те строят, докато спиш. Събуждаш се с една кратка купчинка: няколко въпроса, няколко неща за тестване, един-два лилави диаманта. Кликваш, приемаш и се връщаш към кафето си.","dl.windows":"Приложение за Windows","dl.browser":"Пусни го в браузъра","dl.messenger":"📱 Messenger за телефона ти","dl.soon":"Скоро","dl.notify":"🔔 Кажи ми, когато отвори","dl.notifySmall":"Алфа или бета","hero.secondary":"Аджайл, но екипът никога не се нуждае от кафе за стендъп. (Правят стендъпи така или иначе.)","pitch.h2":"AI-gile с колкото думи искаш","pitch.lede":"Избери дължина, от една дума до 144. Всяка дължина е отделно описание, написано за този размер. Плъзни плъзгача или използвай стрелките.","pitch.rangeLabel":"Дължина в думи","pitch.dice":"🎲 друга версия","pitch.words.one":"{n} дума","pitch.words.other":"{n} думи","pitch.letters.one":"{n} буква","pitch.letters.other":"{n} букви","pitch.chars.one":"{n} знак","pitch.chars.other":"{n} знака","count.line.html.one":"{n} карта на дъската в момента","count.line.html.other":"{n} карти на дъската в момента","people.humans.html.one":"👥 {n} човек","people.humans.html.other":"👥 {n} души","people.agents.html.one":"🤖 {n} агент","people.agents.html.other":"🤖 {n} агента","people.working.html.one":"⚡ {n} работи в момента","people.working.html.other":"⚡ {n} работят в момента","pre.title":"AI-gile: тук се строи нещо","pre.description":"Тук се строи нещо. Дъска, на която AI екипи създават каквото поискаш и те учат по пътя. Засега затворена пре-алфа с приятели.","pre.h1":"Тук се строи нещо. 🤫","pre.line":"Дъска, на която AI екипи създават каквото поискаш и те учат по пътя. Засега затворена пре-алфа с приятели.","pre.btn":"🔔 Кажи ми, когато отвори","pre.peek":"Зад стъклото: истинската дъска, на живо. Всяка карта е цветна лента.","pre.peekFake":"Зад стъклото: така изглежда дъска в работа.","pre.night":"🌙 Нощният пазач поема щафетата · 😴 човекът почива","features.aria":"Какво прави","f.pile.h":"Една купчинка за теб","f.pile.html":"<b>За теб</b> събира всичко, което чака теб, във всички проекти: въпроси, неща за тестване, задачи, които може да свърши само човек. Опашката ти казва кое е следващо и колко ще отнеме.","f.sleep.h":"Екипи, които работят, докато спиш","f.sleep.p":"Всеки проект има лидер и екип от AI агенти. Коментирай карта и екипът се събужда, върши работата и ти я връща със стъпки, които един уморен човек може да следва.","f.tester.h":"Първо проверява AI тестер","f.tester.p":"Преди нещо да стигне до теб, тестер следва стъпките в копие на приложението и показва какво е видял, със снимка на екрана. Прегледай миналите и приеми с един клик.","f.proof.h":"Доказателства, не обещания","f.proof.p":"Всяко предаване показва какво се е променило: файловете, разликата, снимките на екрана. Не е нужно да отваряш всяко приложение, за да видиш дали е готово.","f.chat.h":"Чати с лидерите си","f.chat.p":"Странична лента като в Discord: една икона за проект, лилави диаманти за онова, което чака теб. Пиши на лидер идея; той я превръща в карти и план, с бутон ✅ Давай.","f.tidy.h":"Подрежда се сам","f.tidy.p":"Сродните карти се сливат в една, объркани заглавия се оправят, а проверка на токените държи кода компактен. По-малко неща за превключване, по-малко за мислене.","f.private.h":"Твое, на твоя компютър","f.private.li1":"Дъската работи на твоята собствена машина и отговаря само на теб.","f.private.li2":"Личните съобщения между хората са шифровани от край до край.","f.private.li3":"Без акаунти, без тракери, без бисквитки.","f.lang.h":"На твоя език","f.lang.p":"Над 120 езика, от нидерландски, уелски и японски до пиратски, Йода и клингонски, с бързо превключване обратно към английски за професионалния жаргон.","f.service.h":"От идея до истинска услуга","f.service.p":"Създал си с AI нещо, което хората вече ползват? Отбележи го като услуга и дъската ще ти помогне да го поддържаш добре: проверки на работоспособността, публична страница за състоянието, инциденти с анализ, промени, които искат Go, резервни копия, проверявани всеки ден. Помощта те учи на всяка стъпка по пътя.","msgr.h2":"AI-gile Messenger: екипът ти в джоба","msgr.p1":"Говори с AI екипа си, без да отваряш таблото. Пиши си с лидерите на проектите и с приятелите си, виж стъпките за тест на карта и им отговори, всичко от телефона.","msgr.p2":"За да го свържеш, сканирай QR код от таблото си. За първи път? Приятелски демо чат ще те разведе.","msgr.when":"Първо за Android, после уеб версия за телефони и iPhone.","msgr.who":"Лидерът на проекта ти","msgr.b1":"Поправката на тъмния режим е готова. Искаш ли стъпките за тест?","msgr.b2":"Да, моля!","msgr.b3":"1. Отвори Настройки. 2. Избери Тъмна. Изглежда ли наред?","tl.aria":"Времева линия от първия разговор до пътната карта","tl.h2":"От първия чат до следващото","tl.lede":"Истински дати и часове, в твоята часова зона. След днес това е планът, без обещани дати.","tl.today":"Днес","tl.planned":"планирано","tl.doing":"в процес","tl.cards.one":"{n} карта","tl.cards.other":"{n} карти","join.h2":"Включи се","join.lede":"AI-gile се прави от един брадат чудак с AuDHD и няколко битки с психичното здраве, и от много търпеливи агенти. Засега е частен, в затворена алфа с приятели. Искаш ли да го пробваш, когато се отвори?","join.btn":"Заяви интерес","join.small":"Ще ти пишем по имейл, нищо друго","footer.tag":"AI-gile. Без тракери, без бисквитки, без кафе за стендъп.","footer.licence":"Бизнес лиценз","footer.status":"Статус","footer.privacy":"Какво пазим","footer.thanks":"Разговорите благодарение на ChilledChat","form.sending":"Изпраща се…","form.failed":"Не се получи: опитай пак по-късно.","form.offline":"Не успяхме да стигнем до AI-gile: опитай пак по-късно.","form.keep":"Използваме това само за да ти отговорим, после го изтриваме. Без тракери, без бисквитки.","form.keepLink":"Какво пазим","interest.title":"AI-gile: кажи ми, когато алфата се отвори","interest.description":"Остави имейла си, за да научиш кога се отваря затворената алфа или бета на AI-gile.","interest.h1":"🔔 Кажи ми, когато отвори","interest.lede":"AI-gile е в затворена пре-алфа. Остави имейла си и ще ти пишем веднъж, когато има място за теб.","interest.email":"Твоят имейл","interest.which":"Кой тест?","interest.alpha":"Затворена алфа: рано, грубо, много промени","interest.beta":"Бета: по-стабилна, по-късно","interest.both":"Която и да е, която дойде първа","interest.submit":"Запиши ме в списъка","interest.thanks":"Благодаря! В списъка си.","licence.title":"AI-gile: бизнес лиценз","licence.description":"Използваш ли AI-gile в бизнеса си? Кандидатствай за безплатен бизнес лиценз.","licence.h1":"📜 Бизнес лиценз","licence.lede":"Използваш ли AI-gile на работа? Кажи ни кой си и с какво се занимаваш. Ако върши някаква полза, лицензът е безплатен.","licence.company":"Компания","licence.website":"Уебсайт","licence.what":"С какво се занимаваш","licence.how":"Как помага на света","licence.email":"Имейл","licence.submit":"Кандидатствай","licence.thanks":"Благодаря! Ще ти отговорим по имейл.","status.title":"Статус на AI-gile","status.h1":"Статус на AI-gile","status.quiet":"Всичко е тихо","status.intro":"Работи ли AI-gile в момента? Тази страница проверява сайта, споделянето на дъски, разговорите и изтеглянето на всеки 5 минути.","status.up":"Работи (отговори за {ms} ms)","status.slow":"Не отговори на последната проверка, опитваме пак","status.down":"Не работи: не отговори на последните две проверки","status.svc.web":"Уебсайт","status.svc.web.offers":"Този сайт: какво е AI-gile и формата за интерес","status.svc.boards":"Споделяне на дъски","status.svc.boards.offers":"Публични дъски, съобщения между приятели и покани","status.svc.calls":"Разговори","status.svc.calls.offers":"Глас, видео и споделяне на екрана в AI-gile","status.svc.download":"Изтегляне","status.svc.download.offers":"Инсталаторът за Windows и линковете за покани","status.checking":"Проверява се…","status.offline":"В момента не може да се стигне до услугата за статус (опитва се пак)","status.updated":"обновено {ago}","status.justNow":"току-що","status.min":"преди {n} мин","status.hours":"преди {n} ч","status.days":"преди {n} д","privacy.title":"AI-gile: какво пазим","privacy.h1":"Какво пазим","privacy.lede":"Накратко: само това, което ни пращаш, и не за дълго.","privacy.only":"Само това, което ни пращаш: каквото напишеш във формата, например имейла си. Нищо друго за теб.","privacy.sealed":"Запечатва се, така че сървърът ни да не може да го прочете: в браузъра ти, преди да тръгне (при по-стар браузър – в момента, в който пристигне). Само нашата собствена дъска може да го отвори.","privacy.server":"Изтрива се от сървъра веднага щом стигне до дъската ни. Всичко, което още е там след 30 дни, се изтрива така или иначе.","privacy.board":"Пазим го на дъската си само докато ти отговорим, после го изтриваме и оттам.","privacy.none":"Без тракери, без бисквитки, без анализи.","privacy.local":"Езикът ти и изборът на светла или тъмна тема остават в собствения ти браузър. Никога не ни се изпращат.","privacy.ask":"Искаш да изчезне по-рано? Отговори на имейла ни и ни кажи.","live.h2":"Гледайте как се изгражда, на живо","live.caption":"Всяка карта е скрита: виждате формата на работата, не думите.","live.watching.one":"на живо: {n} гледа","live.watching.other":"на живо: {n} гледат","live.last.now":"Последната карта е преместена току-що","live.last.min.one":"Последната карта е преместена преди {n} мин","live.last.min.other":"Последната карта е преместена преди {n} мин","live.last.hour.one":"Последната карта е преместена преди {n} час","live.last.hour.other":"Последната карта е преместена преди {n} часа","live.last.day.one":"Последната карта е преместена преди {n} ден","live.last.day.other":"Последната карта е преместена преди {n} дни","live.offline":"Таблото на живо си почива за малко. Заповядайте пак скоро.","live.cols":"Backlog|За изпълнение|В процес|Екипът проверява|Чака твоя тест|За екипа|Готово"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Канбан.","Роботи.","Делегирано."]},{"n":2,"texts":["Роботи, канбан.","Агенти, подредени.","Идеи, построени."]},{"n":3,"texts":["Канбан за роботи.","Идеите стават функции.","Безплатен канбан за агенти."]},{"n":5,"texts":["Канбан дъска, водена от агенти.","Ти пишеш карти. Агентите строят.","Безплатно, локално, тествано, малко смахнато."]},{"n":8,"texts":["Безплатна канбан дъска, където работят AI агенти.","Напиши идея. Агентите я строят. Ти я приемаш.","Аджайл за един човек и много търпеливи роботи."]},{"n":13,"texts":["Канбан дъска на твоя компютър, където AI агентите поемат картите и ги изпълняват.","Напиши идея. Екип от агенти я строи. Тестер я проверява накрая.","Безплатно, без акаунти, без тракери: дъска, няколко робота и ти, който решаваш."]},{"n":21,"texts":["AI-gile е канбан дъска за работа с AI агенти за кодиране. Те поемат картите, а ти ги тестваш и приемаш.","Всеки проект получава лидер и екип от AI агенти. Коментирай всяка карта и екипът се залавя за работа.","Безплатна лична дъска със задачи, която работи на твоя компютър. Работниците са роботи. Този, който казва да, си ти."]},{"n":34,"texts":["Слагаш идеи на дъска. Екип от AI агенти ги превръща в работещи функции, тества ги и ти ги връща със стъпки за изпробване. Нищо не се брои за готово, докато ти не кажеш.","AI-gile е домашно направена канбан дъска, която Рич построи с голяма помощ от агентите, които сега управлява. Безплатна е, работи на твоя компютър и се споделя с приятели, не се продава.","Представи си обикновена канбан дъска с колони от Backlog до Готово, само че картите се поемат от AI агенти. Те докладват напредъка, питат, когато заседнат, и винаги чакат твоето одобрение."]},{"n":55,"texts":["AI-gile е канбан дъска, на която екипът е съставен от AI агенти. Всеки проект има лидер, който планира работата, и помощници, които я строят. Когато една функция е готова, AI тестер я изпробва и прави снимка на екрана, след което тя пристига в твоята купчинка. Приеми я или коментирай и те я правят наново.","Започна като начин един човек да следи много сесии за кодиране с AI едновременно и порасна до истинска дъска. Работи на твоята машина, не иска акаунт и няма тракери. Безплатна е за приятели и за всеки любопитен. Също така е недовършена, така че очаквай някоя и друга грапавина и от време на време изненада.","Ето честната версия. Все още трябва ти да измисляш идеите и ти да проверяваш резултатите. AI-gile върши всичко помежду им: подрежда картите, буди правилния агент, когато коментираш, показва точно какво се е променило и държи всичко в една кратка купчинка за теб, без излишен шум."]},{"n":89,"texts":["AI-gile е безплатна канбан дъска, която пускаш на собствения си компютър. Вместо хора всеки проект има екип от AI агенти: лидер, който превръща идеите ти в карти и план, и помощници, които поемат картите по приоритет. Когато нещо е построено, AI тестер следва стъпките за тестване и ти показва какво е видял. После то чака в една купчинка, наречена За теб. Приемаш го или коментираш и екипът опитва отново. Нищо никога не стига до Готово без теб.","Има и функции, които може да не очакваш. Нощна стража държи колоната За правене пълна, докато спиш, като избира карти, които не искат отговор от теб. Брояч на токени показва колко са използвали агентите днес и тази седмица, а Режим без токени им казва да спрат да харчат. Можеш да пишеш на приятели, а личните съобщения са шифровани от край до край. Дъската говори около 120 езика, включително нидерландски, фламандски, пиратски и клингонски. Нищо от това не струва и стотинка и никой не се опитва да ти го продава.","AI-gile е малък личен проект, не компания. Рич искаше да се грижи за няколко проекта с AI кодиране, без да отваря всяко приложение, за да ги проверява, затова двамата с агентите построиха дъска за това, а после я използваха, за да построят останалата част от себе си. В затворена пре-алфа е, което значи, че работи, повечето време, за шепа приятели. Няма страница с цени, няма бюлетин и няма план за растеж. Ако ти звучи полезно, можеш да поискаш да го пробваш, когато се отвори малко повече."]},{"n":144,"texts":["AI-gile е канбан дъска за един човек и много AI агенти. Работи на твоя собствен компютър и е напълно безплатна. Добавяш проекти и всеки проект получава лидер и малък екип. Чатиш с лидера, малко като в Discord, и описваш идея; лидерът я превръща в карти и план, после чака да натиснеш Давай. Екипът минава през картите по приоритет, като използва прост команден ред, направен за езикови модели. Преди нещо да се върне при теб, AI тестер следва стъпките в копие на приложението и прикрепя снимка на екрана. Готовата работа пристига в твоята купчинка с променените файлове и разликата. Приемаш я или оставяш коментар, и екипът се събужда и опитва пак. Само ти можеш да преместиш карта в Готово.","Един ден с AI-gile, приблизително. Вечерта оставяш няколко коментара: този бутон е на грешно място, този списък трябва да е подреден, можем ли да имаме тъмен режим. Лягаш си. Агентите четат коментарите, правят промените, тестват ги и ти ги връщат. Ако За правене се изпразни, нощната стража го допълва от backlog с карти, които не искат отговор от теб. Сутринта има една кратка купчинка: няколко въпроса и няколко неща за изпробване, всяко със стъпки, които може да следва един сънлив човек, и със снимка на екрана как работи. Кликваш, приемаш добрите и връщаш останалите. Брояч на токени показва какво е изразходвано, а Режим без токени е за оскъдните седмици. После закусваш, с което агентите още не могат да помогнат.","Първо, какво AI-gile не е. Не е стартъп, не се продава и никой не събира данните ти. Безплатна дъска е, която работи на твоя компютър, без акаунти, без тракери и без бисквитки. Какво е: едно подредено място да видиш всички проекти с AI кодиране наведнъж, с екип от агенти, който върши картите, и ти, който взимаш решенията. Слива сродните карти, оправя объркани заглавия и следи колко компактен остава кодът. Говори около 120 езика, от нидерландски и фламандски до пиратски и клингонски. Приятелите могат да си пишат, лично и шифровано. Направена е от Рич и много търпеливи агенти, най-вече като използват самата нея. В затворена пре-алфа е, така че на места е грапава. Ако ти звучи забавно, попитай любезно и може да влезеш рано."]}],"quips":{"1":"Една дума. Смело. Може би твърде смело.","3":"Три думи. Вече по-честно от повечето страници на продукти.","8":"Осем думи. Пак по-кратко от стендъп.","21":"Дължините са story points, между другото. Разбира се, че са.","55":"Петдесет и пет думи. Две карти се довършиха, докато четеше това.","144":"Това е дългата. Няма 233. Агентите си легнаха."}},"timeline":{"first-idea.name":"Първата идея","first-idea.line":"Най-първият разговор, преди да съществува и един ред код.","first-board.name":"Първата дъска","first-board.line":"Дъска, която следи собственото си изграждане: карти, колони, дърпане и пускане, проекти.","team-roles.name":"Екип и роли","team-roles.line":"Профили на агенти, шаблони за екипи, пространства и кой какво прави.","install.name":"Инсталиране и версии","install.line":"Zip, който приятел може да инсталира, самообновяване, канали и връщане назад.","usage-saver.name":"Спестяване на ресурси","usage-saver.line":"Мери колко струват пусканията, дръж кода компактен, пази лимита си.","friends.name":"Приятели и споделяне","friends.line":"Лични съобщения, шифровано реле, покани, роли и споделени проекти.","languages.name":"Езици","languages.line":"Всеки екранен текст в езиков файл, първо нидерландски и фламандски.","ai-tester.name":"AI тестер","ai-tester.line":"Тестер проверява всяко предаване първо и показва какво е видял.","website.name":"Уебсайтът","website.line":"aigile.lol, тийзърът и тази времева линия.","streaming.name":"Чат и стрийминг","streaming.line":"Discord, Twitch, OBS, режим за стриймъри, GIF-ове и емоджита.","no-ai.name":"Версия без AI","no-ai.line":"Дъска за хора, които кодират без AI, и публични дъски.","night-watch.name":"Нощна стража","night-watch.line":"Пазач и Scrum Master държат екипите на задачата, докато спиш.","p-more.name":"Всичко останало","p-more.line":"По-малки идеи, които още чакат реда си.","p-android.name":"Телефон и Android","p-android.line":"Стигай до дъската си от телефона, после и с родно Android приложение.","p-release.name":"Алфа и нататък","p-release.line":"Затворена алфа, живият сайт, после бета.","p-languages.name":"Още езици","p-languages.line":"130 езика и режим на потапяне за учещите.","p-engines.name":"Още AI двигатели","p-engines.line":"Избери Claude, Codex, Gemini, Copilot или Cursor за всеки агент.","p-pro.name":"Професионална практика","p-pro.line":"Етикети за риск, врати за сливане, карти за инциденти и предпазни огради.","p-self.name":"Грижа за теб","p-self.line":"Режим на умора, напомняния за грижа за себе си и 4:20.","p-servers.name":"Сървъри и мащаб","p-servers.line":"Глобални настройки на сървъра, роли и планиране за растеж.","p-livestream.name":"Допълнения за стрийминг","p-livestream.line":"Twitch чат, собствени емоджита и публичен жив изглед."},"words":{"button":"📖 Професионален жаргон","h":"📖 Обяснени думи","intro":"Думите, които срещаш в AI-gile, на прост език: как се създава, как се променя безопасно, как да продължи да работи за хората, които го ползват, и как се работи като екип с AI.","search":"Търси дума…","none":"Няма дума, която да съвпада.","close":"Затвори","count":{"one":"{count} дума","other":"{count} думи"},"groups":[{"id":"idea","name":"💡 Idea and discovery"},{"id":"plan","name":"🗺️ Planning the work"},{"id":"agile","name":"🔁 Agile ways of working"},{"id":"build","name":"🛠️ Създаване"},{"id":"test","name":"🧪 Testing and quality"},{"id":"change","name":"🔀 Безопасни промени"},{"id":"run","name":"🛎️ Поддържане на услуга"},{"id":"sec","name":"🔒 Security and privacy"},{"id":"ai","name":"🤖 Working with AI"},{"id":"money","name":"💰 Money and licences"}],"list":[{"id":"discovery","g":"idea","word":"Discovery","text":"The early stage of finding out which problem is worth solving and for whom, before anything gets built.","also":["discovery phase"]},{"id":"problemstmt","g":"idea","word":"Problem statement","text":"One or two sentences saying who has a problem, what it is and why it matters, so everyone aims at the same thing.","also":["problem statements"]},{"id":"user","g":"idea","word":"User","text":"A person who uses what you build. Their needs are what the work is for.","also":["users"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Stakeholder","text":"Anyone who cares how the work turns out or is affected by it, like the people paying for it, using it or supporting it.","also":["stakeholders"]},{"id":"persona","g":"idea","word":"Persona","text":"A made-up but realistic person who stands for one kind of user, so the team can ask “would Sam find this easy?”","also":["personas"]},{"id":"userresearch","g":"idea","word":"User research","text":"Talking to and watching real people to learn what they need, rather than guessing.","also":["user interviews"]},{"id":"journey","g":"idea","word":"User journey","text":"The steps a person takes to get something done, from first hearing about it to finishing, also outside your product. Drawing it out shows where they get stuck.","also":["user journeys","customer journey"]},{"id":"painpoint","g":"idea","word":"Pain point","text":"Something that annoys or slows people down today. Good products take pain points away.","also":["pain points"]},{"id":"assumption","g":"idea","word":"Assumption","text":"Something you believe but haven’t checked yet. Writing assumptions down shows what to test first.","also":["assumptions"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Hypothesis","text":"A best guess you plan to check, with what you expect to happen, like “people will sign up if the first month is free”.","also":["hypotheses"]},{"id":"experiment","g":"idea","word":"Experiment","text":"A small planned test to learn whether an idea works, before betting a lot on it.","also":["experiments"],"noTip":1},{"id":"poc","g":"idea","word":"Proof of concept (PoC)","text":"A quick rough try to see if an idea can work at all. It is usually thrown away once you have the answer.","also":["PoC","proof of concept"]},{"id":"prototype","g":"idea","word":"Prototype","text":"An early model of the product, often clickable pictures, to try the idea on people before building it properly.","also":["prototypes"]},{"id":"wireframe","g":"idea","word":"Wireframe","text":"A simple sketch of a screen showing where things go, without colours or real content.","also":["wireframes"]},{"id":"mockup","g":"idea","word":"Mockup","text":"A detailed picture of how a screen will look, with real colours and text, but nothing works yet.","also":["mockups","mock-up","mock-ups"]},{"id":"bizcase","g":"idea","word":"Business case","text":"The reasons for doing a project: what it costs, what it brings in or saves, and the risks.","also":["business cases"]},{"id":"feasibility","g":"idea","word":"Feasibility","text":"Whether something can really be built and looked after with the time, money and skills you have."},{"id":"outcome","g":"idea","word":"Outcome","text":"The change you want for people, like fewer missed appointments. It matters more than how much you build.","also":["outcomes"],"noTip":1},{"id":"output","g":"idea","word":"Output","text":"Something the team makes, like a new screen or a report. Making it doesn’t automatically mean it helps anyone.","also":["outputs"],"noTip":1},{"id":"successmetric","g":"idea","word":"Success metric","text":"A number that tells you whether the work did what it was for, like more people finishing their order.","also":["success metrics"]},{"id":"kpi","g":"idea","word":"Key performance indicator (KPI)","text":"An important number you watch to see if things are going well, like sign-ups per week.","also":["KPI","KPIs","key performance indicator"]},{"id":"okr","g":"idea","word":"Objectives and key results (OKRs)","text":"A way of setting goals: the objective says what you want, and a few key results are the numbers that show you got there.","also":["OKR","OKRs"]},{"id":"product","g":"plan","word":"Product","text":"The thing being built and looked after for its users, such as an app, a website or a tool.","also":["products"],"noTip":1},{"id":"vision","g":"plan","word":"Product vision","text":"A short statement of who the product helps and where it is heading in the long run.","also":["vision statement"]},{"id":"po","g":"plan","word":"Product owner (PO)","text":"The person who decides what gets built and in what order, so the team always works on what matters most. In AI-gile that is you.","also":["PO","product owners"]},{"id":"pm","g":"plan","word":"Product manager (PM)","text":"The person who looks after a product’s direction: which problems it solves, for whom and why. PM can also mean project manager, so check which.","also":["product managers"]},{"id":"projmgr","g":"plan","word":"Project manager","text":"The person who keeps a project on time and on budget, tracking who does what and by when.","also":["project managers"]},{"id":"roadmap","g":"plan","word":"Roadmap","text":"A rough plan of what is coming over the next months, in order. It shows direction, not exact dates, and changes as you learn.","also":["roadmaps"]},{"id":"milestone","g":"plan","word":"Milestone","text":"A point in a project worth marking, like “first version live” or “100 users”.","also":["milestones"]},{"id":"mvp","g":"plan","word":"Minimum viable product (MVP)","text":"The smallest version of a product that is still useful to real people, so you can learn from them early.","also":["MVP","MVPs","minimum viable product"]},{"id":"requirement","g":"plan","word":"Requirement","text":"Something the finished product must do or be.","also":["requirements"],"noTip":1},{"id":"scope","g":"plan","word":"Scope","text":"What is included in the work and, just as important, what is not.","also":["in scope","out of scope"]},{"id":"scopecreep","g":"plan","word":"Scope creep","text":"When more and more gets added to the work bit by bit, without anyone agreeing on the extra time or cost, so it never quite finishes.","also":["feature creep"]},{"id":"feature","g":"plan","word":"Feature","text":"One thing the product can do for people, like “reset your password”.","also":["features"],"noTip":1},{"id":"epic","g":"plan","word":"Epic","text":"A big piece of work, too large for one go, so it is split into smaller cards.","also":["epics"]},{"id":"story","g":"plan","word":"User story","text":"A small piece of work written from the user’s side: “As a shopper, I want to save my basket, so I can finish later.” It starts a conversation about what to build.","also":["user stories"]},{"id":"ac","g":"plan","word":"Acceptance criteria (AC)","text":"The checks one card must pass to count as done, agreed before work starts, like “the basket is still there after I log out and back in”.","also":["acceptance criteria"]},{"id":"task","g":"plan","word":"Task","text":"A single job to be done, often one small step of a bigger story.","also":["tasks"],"noTip":1},{"id":"ticket","g":"plan","word":"Ticket","text":"Another word for a card: one piece of work or one request, tracked from start to finish.","also":["tickets"]},{"id":"priority","g":"plan","word":"Priority","text":"How important or urgent something is compared with everything else, so the most important work goes first.","also":["priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"Prioritisation","text":"Putting work in order of importance. A common way is MoSCoW: Must have, Should have, Could have, Won’t have this time.","also":["MoSCoW"]},{"id":"estimate","g":"plan","word":"Estimate","text":"A best guess at how big or how long a piece of work is. It is a guess, not a promise.","also":["estimates","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"Story points","text":"A way of guessing the size of work by comparing cards with each other (“about twice as big as that one”) rather than in hours. They aren’t for comparing teams.","also":["story point"]},{"id":"tshirt","g":"plan","word":"T-shirt sizing","text":"Guessing the size of work as S, M, L or XL. Quick and good enough for early planning.","also":["t-shirt sizes"]},{"id":"poker","g":"plan","word":"Planning poker","text":"A game for estimating: everyone shows a size card at the same time, then the highest and lowest explain why.","also":["Scrum poker"]},{"id":"dependency","g":"plan","word":"Dependency","text":"When one piece of work can’t start or finish until another one does.","also":["dependencies"]},{"id":"blocker","g":"plan","word":"Blocker","text":"Anything stopping work from moving forward right now, like a missing answer or a broken tool.","also":["blockers"]},{"id":"deadline","g":"plan","word":"Deadline","text":"The date something must be finished by.","also":["deadlines"],"noTip":1},{"id":"deliverable","g":"plan","word":"Deliverable","text":"Something concrete the work produces and hands over, like a working page or a report.","also":["deliverables"]},{"id":"forecast","g":"plan","word":"Forecast","text":"A prediction of what is likely to happen, like when the work will be done, based on what you know so far.","also":["forecasts"],"noTip":1},{"id":"metric","g":"plan","word":"Metric","text":"Anything you measure and track over time, like page visits or how long a fix takes.","also":["metrics"]},{"id":"feedback","g":"plan","word":"Feedback","text":"What people tell you about your work, good and bad. Getting it early and often is the heart of Agile.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"Идеи и работа, които още не са планирани. Нищо там не се върши, докато не се премести в „За изпълнение“."},{"id":"sprint","g":"agile","word":"Спринт","text":"Кратък период работа (често седмица или две) с уговорен набор карти за привършване.","also":["спринт","спринта","спринтове","спринтовете","sprint","sprints"]},{"id":"standup","g":"agile","word":"Стендъп","text":"Бърза проверка: какво е направил всеки член на екипа, какво ще прави после и какво го спира.","also":["стендъп","стендъпа","стендъпи","стендъпите","standup","stand-up","stand-ups"]},{"id":"kanban","g":"agile","word":"Канбан","text":"Табло с колони (За изпълнение, В процес, Готово), в което картите се движат отляво надясно, докато върви работата."},{"id":"wip","g":"agile","word":"WIP лимит","text":"Work in progress (работа в процес): най-много карти, които една колона трябва да държи, за да довършва екипът нещата, преди да започне още.","also":["WIP","wip лимит"]},{"id":"dod","g":"agile","word":"Определение за „Свършено“","text":"Краткият списък на екипа какво значи „завършено“, например тествано и обяснено, преди картата да ти бъде предадена. Близнакът му, Определението за „Готово за старт“, казва кога картата е достатъчно ясна, за да се започне.","also":["Определение за „Готово за старт“","Definition of Done","Definition of Ready"]},{"id":"retro","g":"agile","word":"Ретро","text":"Поглед назад към това как работи екипът, за да се договори едно нещо за подобрение. В AI-gile ретрото предлага промяна в начина на работа на екипа, а ти казваш Go или Още не.","also":["ретроспектива","retro","retrospective"]},{"id":"swarm","g":"agile","word":"Рояк","text":"Всички на палубата: всеки екип оставя другата работа, за да помогне по един спешен проект, докато се оправи. Другите проекти междувременно чакат.","also":["swarm","swarming"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"Този, който поддържа работата в движение: забелязва заседнали карти, побутва екипите и ти напомня какво чака. В AI-gile Lead Scrum Master прави това за всички проекти.","also":["Lead Scrum Master","скръм мастър"]},{"id":"agile","g":"agile","word":"Agile","text":"A way of working in small steps: build a little, show real results often, learn from what people say and change the plan as you go, instead of planning everything up front.","also":["Agile development","agile ways of working"]},{"id":"manifesto","g":"agile","word":"Agile Manifesto","text":"A short statement written in 2001 by software makers. It puts people, working results, close work with customers and responding to change ahead of heavy plans and paperwork.","also":["Manifesto for Agile Software Development"]},{"id":"waterfall","g":"agile","word":"Waterfall","text":"The older way of working: plan everything, then build it all, then test it all, one stage after another. Changes late on are hard and costly.","also":["waterfall model"]},{"id":"iteration","g":"agile","word":"Iteration","text":"One round of building something, checking it and improving it. Agile work is a chain of these, and a sprint is one kind.","also":["iterations"]},{"id":"increment","g":"agile","word":"Increment","text":"A new working piece added to the product in a sprint or round of work, which fits with what was already there.","also":["increments"]},{"id":"scrum","g":"agile","word":"Scrum","text":"A popular Agile way of working: a small team works in short sprints towards a goal, with set roles and a few regular meetings to plan, check and improve."},{"id":"scrumteam","g":"agile","word":"Scrum team","text":"The small group that does the work in Scrum: a product owner, a Scrum Master and the developers.","also":["Scrum teams"]},{"id":"ceremonies","g":"agile","word":"Scrum events","text":"The regular meetings in Scrum: sprint planning, the daily scrum, the sprint review and the retro. Many people call them ceremonies.","also":["ceremonies","Scrum ceremonies"]},{"id":"sprintplan","g":"agile","word":"Sprint planning","text":"The meeting at the start of a sprint where the team agrees why the sprint matters, which cards to take on and how to start.","also":["planning meeting"]},{"id":"sprintgoal","g":"agile","word":"Sprint goal","text":"One sentence saying what a sprint is for. Small tasks can change along the way, as long as the goal is met.","also":["sprint goals"]},{"id":"sprintbacklog","g":"agile","word":"Sprint backlog","text":"The cards picked for the current sprint, with the team’s plan for doing them.","also":["sprint backlogs"]},{"id":"productbacklog","g":"agile","word":"Product backlog","text":"The full ordered list of everything that might be built for the product, most important at the top. It keeps changing as you learn.","also":["product backlogs"]},{"id":"productgoal","g":"agile","word":"Product goal","text":"The bigger result the product is working towards, which helps the team choose what to do next.","also":["product goals"]},{"id":"refinement","g":"agile","word":"Backlog refinement","text":"Regularly going through the backlog to tidy, split, order and add detail to cards, so they are ready to pick up. Also called backlog grooming.","also":["backlog grooming","refinement"]},{"id":"sprintreview","g":"agile","word":"Sprint review","text":"A meeting at the end of a sprint where the team shows what it finished and hears what people think, to decide what comes next.","also":["sprint reviews"]},{"id":"demo","g":"agile","word":"Demo","text":"Showing finished work working, live, to the people who asked for it.","also":["demos"],"noTip":1},{"id":"timebox","g":"agile","word":"Timebox","text":"A fixed amount of time for something. When it runs out you stop, even if not everything is done.","also":["timeboxed","timeboxes"]},{"id":"velocity","g":"agile","word":"Velocity","text":"How much work a team usually finishes in a sprint, used to plan how much to take on next time. It isn’t a score for how hard people work.","also":["team velocity"]},{"id":"capacity","g":"agile","word":"Capacity","text":"How much work the team can take on in a period, after holidays and other jobs.","noTip":1},{"id":"burndown","g":"agile","word":"Burndown chart","text":"A chart of the work left in a sprint going down day by day. If the line stays flat, something is stuck.","also":["burndown","burn-down chart"]},{"id":"burnup","g":"agile","word":"Burnup chart","text":"A chart of finished work going up over time, next to the total planned, so you can see when you will get there.","also":["burnup","burn-up chart"]},{"id":"kanbanboard","g":"agile","word":"Kanban board","text":"The board itself: a column for each stage of the work, with cards moving across.","also":["Kanban boards"]},{"id":"pullsys","g":"agile","word":"Pull system","text":"A way of working where new work only starts when someone has room to take it on, rather than being pushed onto a full plate.","also":["pull-based"]},{"id":"flow","g":"agile","word":"Flow","text":"How smoothly work moves across the board. Good flow means cards keep moving rather than piling up.","also":["flow of work"],"noTip":1},{"id":"leadtime","g":"agile","word":"Lead time","text":"How long it takes from someone asking for something to it being finished.","also":["lead times"]},{"id":"cycletime","g":"agile","word":"Cycle time","text":"How long a card takes from when work really starts on it to when it is finished.","also":["cycle times"]},{"id":"throughput","g":"agile","word":"Throughput","text":"How many cards get finished in a week, or in any set time.","also":["throughput rate"]},{"id":"bottleneck","g":"agile","word":"Bottleneck","text":"The one stage where work piles up and slows everything behind it, like the narrow neck of a bottle.","also":["bottlenecks"]},{"id":"swimlane","g":"agile","word":"Swimlane","text":"A row across the board that groups cards of one kind, such as urgent work or one team’s cards.","also":["swimlanes","swim lane"]},{"id":"lean","g":"agile","word":"Lean","text":"A way of working that cuts out waste (anything that doesn’t help the customer) and keeps work flowing."},{"id":"waste","g":"agile","word":"Waste","text":"In Lean, anything that takes effort but doesn’t help the customer, like waiting, rework or building things nobody uses.","noTip":1},{"id":"kaizen","g":"agile","word":"Continuous improvement","text":"Getting a little better all the time through small regular changes, then checking they helped. Retros are one way to do it. Also called kaizen.","also":["kaizen"]},{"id":"selforg","g":"agile","word":"Self-organising team","text":"A team that decides for itself how to do the work, rather than being told step by step.","also":["self-organising","self-managing team"]},{"id":"crossfunc","g":"agile","word":"Cross-functional team","text":"A team that has all the skills it needs to finish the work itself, like design, building and testing.","also":["cross-functional"]},{"id":"spike","g":"agile","word":"Spike","text":"A short, timeboxed bit of research to answer a question before committing to the real work.","also":["spikes"]},{"id":"rework","g":"agile","word":"Rework","text":"Doing work again because it wasn’t right the first time.","also":["reworked"]},{"id":"safe","g":"agile","word":"Scaled Agile (SAFe)","text":"Ways of using Agile across many teams in a big organisation. SAFe (the Scaled Agile Framework) is one well known example.","also":["scaled Agile"]},{"id":"repo","g":"build","word":"Хранилище","text":"Папката на проекта с код и пълната му история от къмити, обикновено пазена и в GitHub.","also":["хранилище","хранилища","репо","repo","repository"]},{"id":"branch","g":"build","word":"Клон","text":"Отделна линия работа в кода, за да се правят промени, без да се пипа основната версия.","also":["клон","клона","клонове","клоновете","branch","branches"]},{"id":"commit","g":"build","word":"Къмит","text":"Запазена снимка на кода с кратка бележка какво е променено. Винаги можеш да се върнеш към някой.","also":["къмит","къмита","къмити","къмитите","commit","commits"]},{"id":"push","g":"build","word":"Push","text":"Изпращане на запазените снимки (къмити) от този компютър към GitHub, за да са архивирани и споделени."},{"id":"merge","g":"build","word":"Сливане","text":"Връщане на промените от един клон обратно в основната версия."},{"id":"pr","g":"build","word":"Pull request","text":"Искане промените на един клон да бъдат проверени и слети в основната версия.","also":["PR","pull request"]},{"id":"refactor","g":"build","word":"Рефакториране","text":"Подреждане на кода, без да се променя какво прави: по-малки файлове, по-ясни имена, по-малко повторения."},{"id":"bug","g":"build","word":"Бъг","text":"Нещо, което не работи както трябва.","also":["бъг","бъга","бъгове","бъговете","bug","bugs"]},{"id":"peerreview","g":"build","word":"Колегиална проверка","text":"Втори чифт очи: друг AI проверява работата по всяка карта, преди да стигне до теб, така че да минават по-малко грешки.","also":["преглед на кода","peer review","code review"]},{"id":"code","g":"build","word":"Code","text":"The written instructions that tell a computer what to do. Also called source code.","also":["source code"],"noTip":1},{"id":"proglang","g":"build","word":"Programming language","text":"A language for writing code, such as JavaScript, Python or Java. Different ones suit different jobs.","also":["programming languages"]},{"id":"developer","g":"build","word":"Developer (dev)","text":"Someone who writes and changes code. Also called a programmer or software engineer.","also":["developer","developers","programmer","programmers","software engineer"]},{"id":"software","g":"build","word":"Software","text":"Programs that run on computers and phones, as opposed to the machines themselves (the hardware).","noTip":1},{"id":"app","g":"build","word":"App","text":"Short for application: a program people use to get something done, on a phone, a computer or in a web browser.","also":["apps","application","applications"],"noTip":1},{"id":"webapp","g":"build","word":"Web app","text":"An app that runs in a web browser, so there is nothing to install.","also":["web apps","web application"]},{"id":"frontend","g":"build","word":"Front end","text":"The part of an app you see and click on: the screens, buttons and words, often in your browser.","also":["front-end","frontend"]},{"id":"backend","g":"build","word":"Back end","text":"The behind-the-scenes part of an app that keeps the data and does the work when you click something, like checking your password.","also":["back-end","backend"]},{"id":"fullstack","g":"build","word":"Full stack","text":"Working on both the front end and the back end.","also":["full-stack"]},{"id":"ui","g":"build","word":"User interface (UI)","text":"What a person sees and uses on screen: layout, buttons, menus and text.","also":["UI","user interface"]},{"id":"ux","g":"build","word":"User experience (UX)","text":"How it feels to use something: easy, clear and pleasant, or confusing and slow.","also":["UX","user experience"]},{"id":"accessibility","g":"build","word":"Accessibility (a11y)","text":"Making things usable by everyone, including people who can’t see well, can’t use a mouse or use a screen reader.","also":["a11y"]},{"id":"responsive","g":"build","word":"Responsive design","text":"Making pages fit and work well on any screen size, from a phone to a big monitor."},{"id":"designsys","g":"build","word":"Design system","text":"A shared kit of colours, fonts, buttons and rules, so every screen looks and behaves the same way.","also":["design systems"]},{"id":"architecture","g":"build","word":"Architecture","text":"The overall shape of a system: what the main parts are and how they talk to each other."},{"id":"database","g":"build","word":"Database (DB)","text":"An organised store of information, like a very powerful spreadsheet that the app can read and change.","also":["database","databases","DB"]},{"id":"schema","g":"build","word":"Database schema","text":"The layout of a database: which tables of information it has and what goes in each.","also":["schema"]},{"id":"sql","g":"build","word":"SQL","text":"Short for structured query language: the language used to ask many databases for information or to change it.","also":["Structured Query Language"]},{"id":"data","g":"build","word":"Data","text":"Information kept by a computer, like names, orders or settings.","also":["dataset","datasets"],"noTip":1},{"id":"server","g":"build","word":"Server","text":"A computer that is always on and answers requests from other computers, like sending a web page when you visit it.","also":["servers"]},{"id":"client","g":"build","word":"Client","text":"The side that asks for something, usually your browser or app, talking to a server. In business it also just means a customer.","also":["clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Short for application programming interface: a set menu of requests one program can make to another, like asking a weather service for today’s forecast.","also":["APIs","application programming interface"]},{"id":"endpoint","g":"build","word":"Endpoint","text":"One item on an API’s menu: a web address a program can call to get or send something.","also":["endpoints"]},{"id":"integration","g":"build","word":"Integration","text":"Connecting two systems so they work together, like your shop sending orders to your accounts software.","also":["integrations"]},{"id":"webhook","g":"build","word":"Webhook","text":"A message one system sends to another by itself the moment something happens, like “payment received”.","also":["webhooks"]},{"id":"library","g":"build","word":"Library","text":"Ready-made code someone else wrote that you can reuse instead of writing it yourself.","also":["libraries"],"noTip":1},{"id":"framework","g":"build","word":"Framework","text":"A ready-made structure for building an app that decides much of how the code is laid out, like a house frame you fill in.","also":["frameworks"]},{"id":"sdk","g":"build","word":"Software development kit (SDK)","text":"A box of tools, code and examples for building software for one platform or service.","also":["SDK","SDKs"]},{"id":"softdep","g":"build","word":"Software dependency","text":"A library or tool your code needs to work. Keeping them up to date matters for safety.","also":["software dependencies"]},{"id":"package","g":"build","word":"Package","text":"A bundle of ready-made code you can install and use in a project.","also":["packages"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Package manager","text":"A tool that fetches and updates the packages your code depends on. npm is a common one.","also":["package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"The most widely used tool for keeping the history of code changes, as commits and branches."},{"id":"github","g":"build","word":"GitHub","text":"A website that keeps Git repos online, so teams can share code, review changes and track work."},{"id":"vcs","g":"build","word":"Version control","text":"Keeping a full history of every change to the files, so you can see who changed what and go back if needed. Git does this.","also":["source control","version control system"]},{"id":"clone","g":"build","word":"Clone","text":"Making your own full copy of a repo, with its history, on your computer.","also":["cloned","cloning"]},{"id":"pull","g":"build","word":"Pull","text":"Fetching the latest commits from the shared copy (like GitHub) onto your computer. The opposite of push.","also":["git pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"Main branch","text":"The official version of the code that everyone works from, often called main or master.","also":["master branch"]},{"id":"conflict","g":"build","word":"Merge conflict","text":"When two changes touch the same lines in different ways, so the computer can’t join them and a person has to choose.","also":["merge conflicts"]},{"id":"diff","g":"build","word":"Diff","text":"A view showing exactly what changed between two versions: lines added and lines taken away.","also":["diffs"]},{"id":"fork","g":"build","word":"Fork","text":"Your own copy of someone else’s repo, which you can change without affecting theirs.","also":["forks","forked"]},{"id":"script","g":"build","word":"Script","text":"A short program that does one job by itself, like tidying files or starting the app.","also":["scripts"],"noTip":1},{"id":"build","g":"build","word":"Build","text":"Turning the code into something ready to run, or the ready-to-run result itself.","also":["builds"],"noTip":1},{"id":"compile","g":"build","word":"Compile","text":"Translating code people wrote into a form the computer can run directly.","also":["compiler"]},{"id":"cli","g":"build","word":"Command line (CLI)","text":"A text window where you type instructions for the computer instead of clicking. Also called the terminal.","also":["command line","command-line","CLI","terminal"]},{"id":"config","g":"build","word":"Configuration (config)","text":"The settings that control how software behaves, kept apart from the code so they are easy to change.","also":["config","configuration"],"noTip":1},{"id":"envvar","g":"build","word":"Environment variable","text":"A setting handed to a program when it starts, often used for addresses or passwords so they aren’t written into the code.","also":["environment variables","env var"]},{"id":"debugging","g":"build","word":"Debugging","text":"Hunting down why something isn’t working, and fixing it.","also":["debug","debugged"]},{"id":"pairing","g":"build","word":"Pair programming","text":"Two people (or a person and an AI) working on the same code together, one typing and one checking.","also":["pairing"]},{"id":"docs","g":"build","word":"Documentation (docs)","text":"Written explanations of how something works or how to use it.","also":["documentation","docs"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"The first file to read in a repo: what the project is and how to get it running.","also":["READMEs"]},{"id":"legacy","g":"build","word":"Legacy system","text":"An older system still in use that is hard to change, often because few people still understand it.","also":["legacy systems","legacy code"]},{"id":"techdebt","g":"build","word":"Technical debt","text":"Shortcuts that save time now but make later changes slower, like a loan that builds up interest. Refactoring pays it down.","also":["tech debt"]},{"id":"test","g":"test","word":"Тест","text":"Изпробване на готова работа, за да се провери дали прави каквото е поискано, преди да я приемеш.","also":["тест","теста","тестове","тестовете","тестване","test","tests"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Съкращение от quality assurance (осигуряване на качеството): автоматичните проверки, които се пускат, преди нещо да излезе на живо. Когато QA е червено, нещо се е провалило и не може да излезе на живо, докато не се поправи.","also":["проверки на качеството","осигуряване на качеството","quality checks"]},{"id":"testpile","g":"test","word":"Купчина за тестове","text":"Завършените карти, които чакат да ги пробваш, една след друга. Приеми една или я върни с бележка и идва следващата.","also":["купчини за тестове","test pile"]},{"id":"autotest","g":"test","word":"Automated test","text":"A check the computer runs by itself every time the code changes, to catch mistakes early.","also":["automated tests","automatic tests"]},{"id":"manualtest","g":"test","word":"Manual test","text":"A person trying the work by hand to see if it behaves as it should.","also":["manual tests","manual testing"]},{"id":"unittest","g":"test","word":"Unit test","text":"A small automatic check of one tiny piece of code on its own.","also":["unit tests"]},{"id":"integtest","g":"test","word":"Integration test","text":"A check that several parts work properly together, not just one at a time.","also":["integration tests"]},{"id":"endtoend","g":"test","word":"End-to-end test (E2E)","text":"A test that acts like a real user from start to finish, such as signing up, buying and paying.","also":["E2E","end-to-end tests"]},{"id":"uat","g":"test","word":"User acceptance testing (UAT)","text":"The people who asked for the work try it themselves and say whether it does what they need. AI-gile’s test pile is its version of this.","also":["UAT","acceptance testing"]},{"id":"regression","g":"test","word":"Regression","text":"Something that used to work but broke after a change. Regression tests check that the old things still work.","also":["regressions","regression test","regression tests","regression testing"]},{"id":"smoke","g":"test","word":"Smoke test","text":"A very quick check that the main things work at all, for example right after a change goes live. If it fails, stop and look.","also":["smoke tests"]},{"id":"exploratory","g":"test","word":"Exploratory testing","text":"Trying the product freely and poking at it in different ways, to find problems that planned checks would miss.","also":["exploratory test","exploratory tests"]},{"id":"testcase","g":"test","word":"Test case","text":"One written scenario to try: the steps, and what should happen.","also":["test cases"]},{"id":"coverage","g":"test","word":"Test coverage","text":"How much of the code is checked by automatic tests. More is usually safer, but high coverage alone doesn’t prove it works well.","also":["code coverage"]},{"id":"testdata","g":"test","word":"Test data","text":"Made-up example information used while testing, so no real person’s private details are exposed.","also":["test fixtures"]},{"id":"edgecase","g":"test","word":"Edge case","text":"An unusual situation at the limits, like an empty form or a name with an apostrophe, where things often break.","also":["edge cases"]},{"id":"happypath","g":"test","word":"Happy path","text":"The normal route where everything goes right. Good testing also tries the unhappy paths."},{"id":"perftest","g":"test","word":"Performance testing","text":"Checking how fast something is and how well it copes under strain.","also":["performance test","performance tests"]},{"id":"loadtest","g":"test","word":"Load testing","text":"Checking how a system copes when lots of people use it at once.","also":["load test","load tests"]},{"id":"sectest","g":"test","word":"Security testing","text":"Looking for weaknesses that could let someone misuse a system or see what they shouldn’t.","also":["security test","security tests"]},{"id":"accesstest","g":"test","word":"Accessibility testing","text":"Checking that people with different abilities can use the product, including with a screen reader or only a keyboard.","also":["accessibility test"]},{"id":"linting","g":"test","word":"Linting","text":"An automatic check that spots likely mistakes and messy style in code, like a spelling checker for programs.","also":["linter","lint"]},{"id":"static","g":"test","word":"Static analysis","text":"Checking code for problems by reading it automatically, without running it.","also":["static code analysis"]},{"id":"flaky","g":"test","word":"Flaky test","text":"A test that sometimes passes and sometimes fails for no clear reason, so it can’t be fully trusted.","also":["flaky tests"]},{"id":"repro","g":"test","word":"Reproduce (repro)","text":"Making a bug happen again on purpose by following the same steps, so it can be studied and fixed. Writing those steps down is the most useful part of a bug report.","also":["repro","reproduce","steps to reproduce"]},{"id":"severity","g":"test","word":"Severity","text":"How bad a problem’s effect is, from a small annoyance to everything stopping.","also":["severity level"]},{"id":"deploy","g":"change","word":"Деплой","text":"Пускане на нова версия на живо, например на сървър, където хората я използват."},{"id":"release","g":"change","word":"Версия","text":"Пакет завършена работа с име, който излиза на живо наведнъж, с кратки бележки какво се е променило. 🚀 Версии пише бележките от завършените карти.","also":["версии","релийз","release"]},{"id":"rollback","g":"change","word":"Връщане назад","text":"Връщане към последната версия, която е работила, когато нова създава проблеми. В AI-gile това прави списък за проверка от стъпките за отмяна, записани на всяка промяна.","also":["върни назад","rollback","roll back"]},{"id":"live","g":"change","word":"На живо","text":"Истинската версия, която хората ползват, за разлика от копие за пробване на неща. Разработчиците я наричат и продукция (production).","also":["продукция","продукционна среда","production","live"],"noTip":1},{"id":"change","g":"change","word":"Промяна","text":"Планирана промяна в нещо, на което хората разчитат, първо записана: какво, защо, рискът, кога и как да се отмени. Започни една с 🔀 Подай промяна.","also":["промени","заявка за промяна","change request"],"noTip":1},{"id":"risk","g":"change","word":"Риск","text":"Нещо, което може да се обърка, оценено по това колко е вероятно и колко лошо би било. ⚠️ Рискове ги държи в един списък, с най-високата оценка най-горе, всеки с дата за нов преглед.","also":["рискове","регистър на рисковете"]},{"id":"chgwin","g":"change","word":"Прозорец за промени","text":"Времето, когато промените могат да излизат на живо, например спокойна вечер във вторник. Извън прозорец карта за промяна не може да се завърши, освен ако не е спешна.","also":["прозорци за промени","change window"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Бързо гласуване точно преди промяна да излезе на живо: всеки, който трябва да одобри, казва Go или No go. Продължава само когато са съгласни.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Одобрение","text":"Чакане на „да“, преди да започне работа. Карта, подадена от приятел, или промяна чака в ✅ Одобрения, докато не я одобриш или откажеш.","also":["одобрения","approval"]},{"id":"quiettime","g":"change","word":"Тихо време","text":"Период, например стрийм, демо или нощта, когато нищо не излиза на живо. Екипите продължават да работят и тестват, но излизането на живо чака да свърши. Другаде го наричат замразяване на промените.","also":["тихи времена","замразяване на промените","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"A way of working where the people who build software and the people who run it work as one team, with lots of automation, so changes go live often and safely."},{"id":"cicd","g":"change","word":"CI/CD (continuous integration and delivery)","text":"Everyone’s changes are joined into the main version often and checked automatically each time (continuous integration), so the software is always ready to go live at the press of a button (continuous delivery).","also":["CI/CD","CI","CD","continuous integration","continuous delivery"]},{"id":"contdeploy","g":"change","word":"Continuous deployment","text":"One step further than continuous delivery: every change that passes the checks goes live by itself, with no button to press.","also":["continuous deployments"]},{"id":"pipeline","g":"change","word":"Pipeline","text":"The automatic series of steps a change goes through on its way to live, like build, test, then deploy.","also":["pipelines"]},{"id":"environment","g":"change","word":"Environment","text":"One separate copy of the system for one purpose, such as one to build in, one to test in and the live one.","also":["environments"],"noTip":1},{"id":"devenv","g":"change","word":"Development environment","text":"The copy a developer works in, often on their own computer, where breaking things harms nobody.","also":["dev environment"]},{"id":"testenv","g":"change","word":"Test environment","text":"A separate copy of the system used just for testing, so the real service isn’t touched.","also":["test environments"]},{"id":"staging","g":"change","word":"Staging","text":"A last copy set up just like live, for a final check before a change goes live.","also":["staging environment"]},{"id":"artifact","g":"change","word":"Build artifact","text":"The file or bundle a build produces, ready to be stored, checked or put live.","also":["build artifacts"]},{"id":"hotfix","g":"change","word":"Hotfix","text":"An urgent fix put live quickly, outside the normal plan, because something important is broken.","also":["hotfixes"]},{"id":"patch","g":"change","word":"Patch","text":"A small update that fixes a bug or closes a security hole. Applying security patches quickly matters.","also":["patches","security patch","security patches"]},{"id":"version","g":"change","word":"Version number","text":"A label like 2.4.1 that says which release you have. Often the first number changes for big changes and the last for small fixes.","also":["version numbers","semantic versioning"]},{"id":"relnotes","g":"change","word":"Release notes","text":"A short plain list of what changed in a release, for the people who use it, including fixes and known limits. Also called a changelog.","also":["changelog","change log"]},{"id":"flag","g":"change","word":"Feature flag","text":"An on and off switch for a feature, so new work can go live hidden and be turned on (or off again) without a new release.","also":["feature flags","feature toggle","feature toggles"]},{"id":"rollfwd","g":"change","word":"Roll forward","text":"Fixing a bad release by quickly putting out a new, corrected version instead of going back to the old one.","also":["rolling forward","rolled forward"]},{"id":"canary","g":"change","word":"Canary release","text":"Putting a change live for a small group first, and for everyone only once it looks fine. Named after the canaries miners took underground as an early warning.","also":["canary releases","canary"]},{"id":"bluegreen","g":"change","word":"Blue-green deployment","text":"Keeping two copies of the live system and switching people over to the new one in one go, so you can switch straight back if it goes wrong.","also":["blue-green","blue green deployment"]},{"id":"zerodown","g":"change","word":"Zero-downtime deployment","text":"Putting a new version live without the service ever stopping for its users.","also":["zero downtime","zero-downtime"]},{"id":"chgenable","g":"change","word":"Change enablement","text":"Helping changes succeed: weighing the risk, getting the right approval and picking a good time. Also called change management.","also":["change management"]},{"id":"cab","g":"change","word":"Change advisory board (CAB)","text":"A group that looks over important changes and agrees whether and when they may go ahead.","also":["CAB"]},{"id":"stdchange","g":"change","word":"Standard change","text":"A low-risk change done the same tried and tested way each time, so it is approved in advance.","also":["standard changes"]},{"id":"normchange","g":"change","word":"Normal change","text":"A change that needs to be checked and approved before it goes ahead.","also":["normal changes"]},{"id":"emergchange","g":"change","word":"Emergency change","text":"A change that must happen right away to fix or prevent serious trouble, with a quicker approval to match.","also":["emergency changes"]},{"id":"automation","g":"change","word":"Automation","text":"Getting the computer to do a repeated job by itself, so it is quicker and done the same way every time.","also":["automated"],"noTip":1},{"id":"infra","g":"change","word":"Infrastructure","text":"The machines, networks and services that software runs on.","also":["infra"]},{"id":"iac","g":"change","word":"Infrastructure as code (IaC)","text":"Describing your servers and settings in files kept with the code, so they can be rebuilt exactly the same way every time.","also":["IaC"]},{"id":"cloud","g":"change","word":"Cloud","text":"Renting computers, storage and services from a big provider over the internet, instead of owning the machines yourself.","also":["the cloud","cloud computing"]},{"id":"provider","g":"change","word":"Cloud provider","text":"A company that rents out computing over the internet, such as Amazon Web Services (AWS), Microsoft Azure or Google Cloud.","also":["cloud providers"]},{"id":"hosting","g":"change","word":"Hosting","text":"Where your app or website lives and runs so people can reach it, usually rented from a company."},{"id":"domain","g":"change","word":"Domain name","text":"The web address people type, like example.com. You rent it by the year, so it must be renewed.","also":["domain names","domain"]},{"id":"dns","g":"change","word":"DNS","text":"Short for domain name system: the internet’s address book, which turns a name like example.com into the address of the right computer.","also":["domain name system"]},{"id":"container","g":"change","word":"Container","text":"A sealed package holding an app and everything it needs, so it runs the same on any computer. Docker is the best known tool.","also":["containers","Docker"],"noTip":1},{"id":"vm","g":"change","word":"Virtual machine (VM)","text":"A pretend computer running inside a real one, so one big machine can act as many.","also":["VM","VMs","virtual machines"]},{"id":"serverless","g":"change","word":"Serverless","text":"Running code without looking after any servers yourself: the provider runs it when needed and you pay for what you use."},{"id":"lb","g":"change","word":"Load balancer","text":"Something that spreads visitors across several servers, so no single one gets overwhelmed.","also":["load balancers"]},{"id":"cache","g":"change","word":"Cache","text":"A handy store of recent results kept close by, so the same thing doesn’t have to be fetched or worked out again. Clearing it can fix pages that look out of date.","also":["caches","caching","cached"]},{"id":"cdn","g":"change","word":"Content delivery network (CDN)","text":"A worldwide set of servers holding copies of your pages and pictures near your visitors, so they load quickly.","also":["CDN"]},{"id":"migration","g":"change","word":"Migration","text":"Moving data or systems from an old setup to a new one, or carefully changing how a database is laid out.","also":["migrations","database migration"]},{"id":"service","g":"run","word":"Услуга","text":"Нещо, което си създал и на което хората разчитат, като уебсайт или приложение, за което се грижат, за да продължи да работи. Отметни „Този проект е услуга“ и кажи какво предлага, кой го ползва и кой е дежурен.","also":["услуги","service"]},{"id":"uptimepct","g":"run","word":"Uptime","text":"How much of the time a service is working, usually as a percentage. 99.9% still allows about 43 minutes down a month.","also":["uptime percentage"]},{"id":"uptime","g":"run","word":"Проверка на работоспособността","text":"Автоматична проверка на всеки няколко минути дали услугата ти още отговаря. Ако се провали няколко пъти поред, AI-gile сам отваря карта за инцидент.","also":["работоспособност","uptime","uptime check"]},{"id":"statuspage","g":"run","word":"Страница за състоянието","text":"Публична страница, която показва дали услугата работи (зелено, оранжево или червено) с последната новина, за да могат ползващите я да проверят, вместо да питат.","also":["статус страница","status page"]},{"id":"desk","g":"run","word":"Бюро за обслужване","text":"Мястото, където пристигат въпроси и сигнали от хората, които ползват услугата ти. AI-gile разпределя всеки като заявка, инцидент или идея и казва, ако прилича на нещо, което вече е съобщено.","also":["бюра за обслужване","бюро за помощ","поддръжка"]},{"id":"svcrequest","g":"run","word":"Заявка за услуга","text":"Някой иска нещо обичайно, например нов акаунт или малко помощ, вместо да съобщава, че нещо е развалено. Чака реда си; инцидентът е с предимство.","also":["заявки за услуга"]},{"id":"incident","g":"run","word":"Инцидент","text":"Нещо, което е развалено за хората, които го ползват в момента, например сайтът не работи. Карта 🔥 инцидент минава пред опашката: да проработи отново е на първо място.","also":["инциденти","incident"]},{"id":"major","g":"run","word":"Голям инцидент","text":"Голям инцидент: засегнати са много хора или пари или данни са в риск. Един бутон слага всички екипи върху него (рояк), събужда дежурния и иска обновяване на състоянието на всеки 30 минути.","also":["големи инциденти","major incident"]},{"id":"oncall","g":"run","word":"Дежурство","text":"Да си този, който отговаря, когато нещо се счупи, дори през нощта. Всяка услуга има дежурен член на екипа, когото събуждат първи за нейните инциденти.","also":["дежурен","on call","on-call"]},{"id":"replyby","g":"run","word":"Срок за отговор","text":"Колко дълго една карта може да чака първи отговор, например час за инцидент. След това получава червен часовник, така че нищо да не бъде тихо забравено. Нарича се и цел за отговор.","also":["срокове за отговор","цел за отговор","response target"]},{"id":"postmortem","g":"run","word":"Анализ след инцидента","text":"Кратък поглед назад след инцидент: какво стана, какво помогна и какво да се промени, без да се обвинява никой. Инцидент не може да се затвори без такъв.","also":["post-mortem","postmortem","преглед след инцидент"]},{"id":"problem","g":"run","word":"Проблем","text":"Скритата причина зад един или повече инциденти. Карта 🧩 проблем групира инцидентите, които все се връщат, за да се намери причината и да се поправи завинаги.","also":["проблеми","problem"],"noTip":1},{"id":"rootcause","g":"run","word":"Първопричина","text":"Истинската причина нещо да се счупи, а не само това, което си видял да се обърка. Поправи първопричината и инцидентът спира да се връща.","also":["първопричини","основна причина","root cause"]},{"id":"workaround","g":"run","word":"Заобиколно решение","text":"Начин нещата да продължат да работят, докато истинската поправка е готова, например рестартиране на нещо, когато забие. Записва се на картата на проблема, за да не трябва никой да го измисля отново.","also":["заобиколни решения","workaround"]},{"id":"knownerror","g":"run","word":"Известна грешка","text":"Проблем, чиято причина е ясна и който има заобиколно решение, но още не е поправен. 🧩 Известни грешки ги изброява, за да ползват всички заобиколното решение, вместо да ровят отново.","also":["известни грешки","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Инструкции стъпка по стъпка за поправяне на познат вид проблем, за да се прави всеки път по един и същ начин и бързо. След голям инцидент екипът може да предложи такъв, за да го одобриш.","also":["runbooks","наръчник","наръчник за действие"]},{"id":"ci","g":"run","word":"Конфигурационен елемент","text":"Едно нещо, от което зависи услугата ти, например сървър, домейн, сертификат, ключ или доставчик. 🗂️ Конфигурационни елементи ги изброява за всяка услуга, за да виждаш какво засяга даден инцидент и какво трябва да се поднови или архивира.","also":["конфигурационни елементи"]},{"id":"expiry","g":"run","word":"Срок на валидност","text":"AI-gile следи дати като изтичането на сертификат или домейн. До 30 дни преди датата създава една карта за подновяване, за да не спре нищо да работи изневиделица.","also":["срокове на валидност","изтичане","следене на изтичането"]},{"id":"backup","g":"run","word":"Резервно копие","text":"Запазено копие на данните ти от по-рано, на което да се опреш, ако нещо се изгуби или повреди. AI-gile прави резервно копие на дъските ти всеки ден.","also":["резервни копия","бекъп","backup"]},{"id":"restore","g":"run","word":"Възстановяване","text":"Връщане на данни от резервно копие. Резервното копие наистина важи чак когато знаеш, че може да се възстанови, затова си струва да го пробваш от време на време.","also":["възстанови","възстановено","restore"]},{"id":"svcreview","g":"run","word":"Преглед на услугата","text":"Поглед назад към един месец от услугата: отворени и оправени инциденти, колко бързо хората са получили отговор, време на работа и изразходвани токени. Месечният преглед показва това за всяка услуга.","also":["прегледи на услугата","месечен преглед","месечни прегледи"]},{"id":"accessreview","g":"run","word":"Преглед на достъпа","text":"На всеки 90 дни проверка кой все още може да влезе: линкове за споделяне, роли на приятели и пазени тайни. Запазваш или премахваш всеки, за да не остава стар достъп.","also":["прегледи на достъпа"]},{"id":"improvements","g":"run","word":"Списък с подобрения","text":"Всичко, в което екипът реши да стане по-добър, на едно място: предложения от ретро, действия от прегледи и поправки на проблеми, всяко със състоянието си. Намираш го в 📈 Подобрения.","also":["списъци с подобрения","подобрения"]},{"id":"tokencap","g":"run","word":"Лимит на токените","text":"Месечен лимит на токените, които агентите на една услуга могат да използват. При 80% получаваш предупреждение; при 100% фоновата им работа чака до следващия месец или докато не вдигнеш лимита.","also":["лимити на токените"]},{"id":"svcmgmt","g":"run","word":"Service management","text":"Everything involved in keeping a service useful and working for the people who rely on it, day after day."},{"id":"itil","g":"run","word":"ITIL","text":"A widely used guide to good service management, covering things like incidents, problems and changes. The name once stood for IT Infrastructure Library."},{"id":"itsm","g":"run","word":"IT service management (ITSM)","text":"Running technology as a service for people, with clear ways to handle requests, incidents, changes and improvements.","also":["ITSM"]},{"id":"managed","g":"run","word":"Managed service","text":"A service someone else runs and looks after for you, under an agreement about how well it must work.","also":["managed services"]},{"id":"svcowner","g":"run","word":"Service owner","text":"The person who answers for a service as a whole: how well it works, what it costs and how it improves.","also":["service owners"]},{"id":"sla","g":"run","word":"Service level agreement (SLA)","text":"A written promise to customers about how well a service will work, like “up 99.9% of the time” or “answered within an hour”, often with money back if it is broken.","also":["SLA","SLAs","service level agreement"]},{"id":"slo","g":"run","word":"Service level objective (SLO)","text":"The team’s own target for how well a service should work over a period, usually set a bit stricter than the SLA to be safe.","also":["SLO","SLOs"]},{"id":"sli","g":"run","word":"Service level indicator (SLI)","text":"The actual measurement you check against a target, like the share of visits that loaded fine.","also":["SLI","SLIs"]},{"id":"availability","g":"run","word":"Availability","text":"Whether people can use a service when they need it, often measured as uptime.","also":["high availability"]},{"id":"downtime","g":"run","word":"Downtime","text":"Time when a service isn’t working or is switched off, planned or not.","also":["down time"]},{"id":"errorbudget","g":"run","word":"Error budget","text":"The small amount of failure your reliability target allows. While some is left you can take risks with changes; once it is used up, you slow down.","also":["error budgets"]},{"id":"outage","g":"run","word":"Outage","text":"A time when a service is down or badly broken for its users.","also":["outages"]},{"id":"degraded","g":"run","word":"Degraded","text":"Working, but badly: slow, or with some parts not working.","also":["degraded service"]},{"id":"monitoring","g":"run","word":"Monitoring","text":"Watching a service automatically all the time, so problems are spotted, ideally before users notice."},{"id":"observability","g":"run","word":"Observability","text":"How well you can tell what is going on inside a system from the outside, using its logs, numbers and traces.","also":["o11y"]},{"id":"log","g":"run","word":"Log","text":"A running diary a program keeps of what it is doing, used to work out what went wrong.","also":["logs","logging"],"noTip":1},{"id":"trace","g":"run","word":"Trace","text":"A record of how one request travels through the different parts of a system, step by step, showing where it slowed down.","also":["traces","tracing"]},{"id":"latency","g":"run","word":"Latency","text":"How long something takes to answer, like the wait between clicking and the page appearing."},{"id":"alert","g":"run","word":"Alert","text":"An automatic message that something needs attention, like the website not answering.","also":["alerts","alerting"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Alert fatigue","text":"When there are so many alerts that people start ignoring them, including the important ones.","also":["alarm fatigue"]},{"id":"dashboard","g":"run","word":"Dashboard","text":"A screen showing the most important numbers and statuses at a glance.","also":["dashboards"],"noTip":1},{"id":"paging","g":"run","word":"Paging","text":"Urgently calling or waking the on-call person about a problem.","also":["paged"]},{"id":"escalation","g":"run","word":"Escalation","text":"Bringing in someone with more skill or authority when an issue can’t be sorted at the current level, or not fast enough.","also":["escalate","escalated"]},{"id":"triage","g":"run","word":"Triage","text":"Quickly sorting incoming issues by how urgent and important they are, so the worst gets handled first.","also":["triaged"]},{"id":"impact","g":"run","word":"Impact","text":"How much something affects people: how many, and how badly.","noTip":1},{"id":"urgency","g":"run","word":"Urgency","text":"How quickly something needs to be dealt with. Impact and urgency together set the priority.","noTip":1},{"id":"plevels","g":"run","word":"Priority levels (P1, P2…)","text":"Labels for how urgent an issue is. P1 is the most serious and needs action straight away.","also":["P1","P2","P3","P4"]},{"id":"queue","g":"run","word":"Ticket queue","text":"The list of requests and incidents waiting to be picked up.","also":["ticket queues"]},{"id":"tiers","g":"run","word":"First line and second line","text":"Levels of support: first line takes the call and fixes simple things; second line has deeper skills for harder ones. Also called tier 1 and tier 2.","also":["first-line support","tier 1","tier 2"]},{"id":"ic","g":"run","word":"Incident commander","text":"The one person who leads the response to an incident, so everyone knows who decides and who does what.","also":["incident commanders"]},{"id":"responsetime","g":"run","word":"Response time","text":"How long it takes before someone first picks up a request or incident.","also":["response times"]},{"id":"resolution","g":"run","word":"Resolution time","text":"How long it takes to fully sort out a request or incident, from report to fixed.","also":["resolution times","time to resolve"]},{"id":"mttr","g":"run","word":"Mean time to recover (MTTR)","text":"On average, how long it takes to get a service working again after it breaks. MTTR can mean slightly different things, so say what you measure.","also":["MTTR","mean time to restore"]},{"id":"mtbf","g":"run","word":"Mean time between failures (MTBF)","text":"On average, how long a service runs before something breaks.","also":["MTBF"]},{"id":"cmdb","g":"run","word":"Configuration management database (CMDB)","text":"The list of all your configuration items and how they connect, so you can see what depends on what.","also":["CMDB"]},{"id":"asset","g":"run","word":"Asset","text":"Anything of value you own or pay for to run the service, like a laptop, a software licence or a domain.","also":["assets"],"noTip":1},{"id":"capplan","g":"run","word":"Capacity planning","text":"Making sure there will be enough computer power, storage and people for what is coming.","also":["capacity plan"]},{"id":"scaling","g":"run","word":"Scaling","text":"Coping with more users by giving a machine more power (scaling up) or adding more machines (scaling out).","also":["scale up","scale out","scaling up","scaling out"]},{"id":"bcp","g":"run","word":"Business continuity","text":"Plans for keeping the important things going when something big goes wrong, like losing an office, a key supplier or the computers.","also":["business continuity plan"]},{"id":"dr","g":"run","word":"Disaster recovery (DR)","text":"The plan and tools for getting a service back after something serious, like losing a whole data centre.","also":["disaster recovery"]},{"id":"rto","g":"run","word":"Recovery time objective (RTO)","text":"The longest a service may be down after a disaster before it must be working again.","also":["RTO"]},{"id":"rpo","g":"run","word":"Recovery point objective (RPO)","text":"How much recent data you could afford to lose, measured in time. An RPO of one hour means backups at least every hour.","also":["RPO"]},{"id":"redundancy","g":"run","word":"Redundancy","text":"Having spares ready, like a second server, so one failure doesn’t stop the service."},{"id":"failover","g":"run","word":"Failover","text":"Switching over to a spare system by itself when the usual one fails.","also":["fail over"]},{"id":"spof","g":"run","word":"Single point of failure","text":"One part that takes everything down with it when it breaks, because there is no spare.","also":["single points of failure","SPOF"]},{"id":"maintwin","g":"run","word":"Maintenance window","text":"A planned time when a service may be paused or slow for upkeep, announced to users in advance.","also":["maintenance windows","planned maintenance"]},{"id":"handover","g":"run","word":"Handover","text":"Passing work, knowledge and responsibility to another person or team, so nothing gets dropped.","also":["handovers"]},{"id":"kb","g":"run","word":"Knowledge base","text":"A collection of help articles and answers, for users and for the team.","also":["knowledge bases"]},{"id":"csat","g":"run","word":"Customer satisfaction (CSAT)","text":"A score from users saying how happy they were, often asked after a request is closed.","also":["CSAT"]},{"id":"supplier","g":"run","word":"Supplier","text":"An outside company you rely on, like your hosting provider. Also called a vendor or third party.","also":["suppliers","vendor","vendors","third party"],"noTip":1},{"id":"retire","g":"run","word":"Service retirement","text":"Switching a service off for good, safely: telling its users, dealing with its data and access, and stopping its costs.","also":["retiring a service"]},{"id":"eol","g":"run","word":"End of life (EOL)","text":"When a product stops getting updates or support from its maker, so it should be replaced.","also":["EOL","end-of-life"]},{"id":"cybersec","g":"sec","word":"Cybersecurity","text":"Protecting systems and data from being broken into, stolen or damaged.","also":["cyber security"]},{"id":"authn","g":"sec","word":"Authentication","text":"Checking who someone is, usually with a password or a code. Often shortened to authn.","also":["authn"]},{"id":"authz","g":"sec","word":"Authorisation","text":"Checking what someone is allowed to do once you know who they are. Often shortened to authz.","also":["authz","authorization"]},{"id":"mfa","g":"sec","word":"Multi-factor authentication (MFA)","text":"Logging in with two or more proofs, like a password plus a code on your phone. Also called two-factor (2FA).","also":["MFA","2FA","two-factor","two-factor authentication"]},{"id":"sso","g":"sec","word":"Single sign-on (SSO)","text":"Logging in once to get into many systems, like using your work account everywhere.","also":["SSO"]},{"id":"pwmgr","g":"sec","word":"Password manager","text":"An app that creates strong passwords and remembers them for you.","also":["password managers"]},{"id":"secret","g":"sec","word":"Secret","text":"A password, key or other private code a program uses to get into something. It must never be shared or written into the code.","also":["secrets"],"noTip":1},{"id":"apikey","g":"sec","word":"API key","text":"A secret code that lets a program use another service’s API, and shows who is using (and paying for) it.","also":["API keys"]},{"id":"accesstoken","g":"sec","word":"Access token","text":"A temporary pass that proves a program is allowed in, so it doesn’t need your password each time. Not the same as an AI token.","also":["access tokens"]},{"id":"encryption","g":"sec","word":"Encryption","text":"Scrambling information so only someone with the right key can read it.","also":["encrypted","encrypt"]},{"id":"https","g":"sec","word":"HTTPS","text":"The secure way web pages travel, shown by the padlock in your browser, so nobody in between can read or change them."},{"id":"cert","g":"sec","word":"SSL/TLS certificate","text":"A digital ID card that lets a website prove who it is and use HTTPS. It expires, so it must be renewed.","also":["TLS certificate","SSL certificate","certificate","certificates"]},{"id":"permissions","g":"sec","word":"Permissions","text":"The rules for who may see or change what.","also":["permission"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Least privilege","text":"Giving each person or program only the access they truly need, for only as long as they need it.","also":["principle of least privilege"]},{"id":"rbac","g":"sec","word":"Role-based access control (RBAC)","text":"Giving access by role, like viewer or editor, rather than person by person.","also":["RBAC","role-based access"]},{"id":"vuln","g":"sec","word":"Vulnerability","text":"A weakness that someone could use to break in or cause harm.","also":["vulnerabilities"]},{"id":"zeroday","g":"sec","word":"Zero-day","text":"A weakness attackers know about before the makers have had any time to fix it.","also":["zero-days","zero day"]},{"id":"malware","g":"sec","word":"Malware","text":"Harmful software, like viruses, made to damage, spy or steal."},{"id":"ransomware","g":"sec","word":"Ransomware","text":"Malware that locks up your files and demands money to unlock them. Good backups are the best defence.","also":["ransomware attack"]},{"id":"phishing","g":"sec","word":"Phishing","text":"Fake messages that try to trick you into giving away passwords or money, or opening something harmful.","also":["phishing email","phishing emails"]},{"id":"socialeng","g":"sec","word":"Social engineering","text":"Tricking people, rather than computers, into giving access, like a fake call from “IT support”."},{"id":"firewall","g":"sec","word":"Firewall","text":"A guard that decides which network traffic may come in or go out.","also":["firewalls"]},{"id":"vpn","g":"sec","word":"VPN","text":"Short for virtual private network: a private, scrambled link over the internet, often used to reach work systems safely.","also":["virtual private network"]},{"id":"ddos","g":"sec","word":"Denial of service (DoS, DDoS)","text":"Flooding a service with so much fake traffic that real people can’t use it. DDoS means it comes from many computers at once.","also":["DoS","DDoS","denial of service","DDoS attack"]},{"id":"pentest","g":"sec","word":"Penetration test (pen test)","text":"Hiring friendly experts to try to break in, so weaknesses are found before real attackers find them.","also":["pen test","pen testing","penetration testing","pentest"]},{"id":"audit","g":"sec","word":"Security audit","text":"A careful check of how well something is protected, against a list of good practice.","also":["security audits"]},{"id":"threatmodel","g":"sec","word":"Threat modelling","text":"Thinking through who might attack something, how, and what you would do to stop them.","also":["threat model","threat modeling"]},{"id":"breach","g":"sec","word":"Data breach","text":"When private information gets out to people who shouldn’t have it, or is lost or changed without permission.","also":["data breaches"]},{"id":"pii","g":"sec","word":"Personal data","text":"Any information about a person who can be identified, like a name, email address or location. Also called PII.","also":["PII","personally identifiable information"]},{"id":"gdpr","g":"sec","word":"GDPR","text":"The European law on personal data (the UK has its own version): collect only what you need, keep it safe, and let people see or delete theirs.","also":["General Data Protection Regulation"]},{"id":"dataprot","g":"sec","word":"Data protection","text":"Looking after personal data properly and within the law.","also":["data protection law"]},{"id":"privacypolicy","g":"sec","word":"Privacy policy","text":"A public page saying what personal data you collect, why, and what you do with it.","also":["privacy statement","privacy notice"]},{"id":"consent","g":"sec","word":"Consent","text":"A person’s clear, free yes to their data being used in a particular way. They can take it back at any time.","also":["opt-in"],"noTip":1},{"id":"cookie","g":"sec","word":"Cookie","text":"A small file a website saves in your browser to remember things, like being logged in. Some need your consent first.","also":["cookies"],"noTip":1},{"id":"minimisation","g":"sec","word":"Data minimisation","text":"Collecting and keeping only the personal data you really need for the job.","also":["data minimization"]},{"id":"retention","g":"sec","word":"Data retention","text":"How long data is kept before it is deleted. Keeping it no longer than needed is safer and often the law.","also":["retention period"]},{"id":"anon","g":"sec","word":"Anonymisation","text":"Changing data so nobody can reasonably be identified from it any more.","also":["anonymised","anonymization","anonymous data"]},{"id":"pseudo","g":"sec","word":"Pseudonymisation","text":"Swapping names and other details for codes, with a key kept apart to link them back. It is still personal data.","also":["pseudonymised","pseudonymization"]},{"id":"dpa","g":"sec","word":"Data processing agreement (DPA)","text":"A contract saying how a supplier may handle personal data on your behalf.","also":["DPA"]},{"id":"dpia","g":"sec","word":"Data protection impact assessment (DPIA)","text":"A careful look, before you start, at how a plan to use personal data could affect people and how to lower the risks.","also":["DPIA"]},{"id":"auditlog","g":"sec","word":"Audit log","text":"A record of who did what and when, so actions can be checked later.","also":["audit logs","audit trail"]},{"id":"compliance","g":"sec","word":"Compliance","text":"Following the laws, rules and standards that apply to you, and being able to show that you do.","also":["compliant"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"A well known international standard for managing information security. Companies can be certified against it.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"A US report, checked by outside auditors, showing a company looks after customer data properly.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Агент","text":"AI, който работи самостоятелно по задача: чете кода, прави промени, пуска проверки и докладва.","also":["агент","агента","агенти","агентите","agent","agents"]},{"id":"token","g":"ai","word":"Токен","text":"Единицата, в която се брои използването на AI: грубо няколко букви прочетен или написан текст. По-малко токени, повече останало от плана.","also":["токен","токена","токени","токените","token","tokens"]},{"id":"hook","g":"ai","word":"Hook","text":"Малка команда, която се изпълнява сама в определен момент, напр. когато започне AI сесия, за да чува екипът коментарите ти.","also":["hook","hook-ове","hook-а","hooks"]},{"id":"ai","g":"ai","word":"Artificial intelligence (AI)","text":"Computer systems that do things we usually think need a person, like writing, answering questions or recognising pictures.","also":["AI","artificial intelligence"],"noTip":1},{"id":"ml","g":"ai","word":"Machine learning (ML)","text":"A way of making computers learn patterns from lots of examples, instead of giving them exact rules.","also":["machine learning"]},{"id":"model","g":"ai","word":"Model","text":"The trained “brain” of an AI system, built by learning from huge numbers of examples. Models differ in skill, speed and price.","also":["models","AI model"],"noTip":1},{"id":"llm","g":"ai","word":"Large language model (LLM)","text":"An AI model trained on vast amounts of text, so it can read and write language.","also":["LLM","LLMs"]},{"id":"genai","g":"ai","word":"Generative AI","text":"AI that creates new things, like text, pictures or code, rather than only sorting or spotting them.","also":["GenAI"]},{"id":"chatbot","g":"ai","word":"Chatbot","text":"A program you talk with in everyday language, by typing or speaking.","also":["chatbots"]},{"id":"prompt","g":"ai","word":"Prompt","text":"What you give an AI: your question or instructions, plus anything you hand it. Clearer prompts usually get better answers.","also":["prompts"]},{"id":"prompteng","g":"ai","word":"Prompt engineering","text":"The skill of writing prompts that get reliable, useful results."},{"id":"sysprompt","g":"ai","word":"System prompt","text":"Background instructions an AI gets before the conversation starts, setting its role and rules. They weigh more than what you type.","also":["system prompts","system instruction","system instructions"]},{"id":"context","g":"ai","word":"Context","text":"Everything the AI can see while it works: the instructions, your messages, files it has read and earlier replies.","noTip":1},{"id":"ctxwin","g":"ai","word":"Context window","text":"How much an AI can keep in mind at once, measured in tokens. Past that, older parts get dropped or summarised.","also":["context windows"]},{"id":"session","g":"ai","word":"Session","text":"One working conversation with an AI, from start to finish. A new session starts with a fresh memory.","also":["sessions"],"noTip":1},{"id":"memory","g":"ai","word":"Memory","text":"Notes an AI keeps between sessions, so it remembers your preferences and past decisions.","noTip":1},{"id":"hallucination","g":"ai","word":"Hallucination","text":"When an AI says something that sounds sure of itself but is made up or wrong. Check important facts.","also":["hallucinations","hallucinate","hallucinates"]},{"id":"training","g":"ai","word":"Training","text":"Teaching a model by showing it huge numbers of examples, before anyone uses it.","also":["trained"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Training data","text":"The examples a model learned from. Its knowledge stops at the date that data was collected.","also":["training set"]},{"id":"cutoff","g":"ai","word":"Knowledge cutoff","text":"The date an AI’s built-in knowledge ends. It won’t know about later things unless it looks them up.","also":["training cutoff"]},{"id":"finetune","g":"ai","word":"Fine-tuning","text":"Extra training of an existing model on your own examples, to make it better at one particular job.","also":["fine-tune","fine-tuned","fine tuning"]},{"id":"inference","g":"ai","word":"Inference","text":"An AI model actually being used to answer something, as opposed to being trained.","also":["model inference"]},{"id":"tooluse","g":"ai","word":"Tool use","text":"An AI being able to do things, not just talk: run commands, read files or search the web, through tools the app gives it.","also":["tool calling","tool call","tool calls"]},{"id":"subagent","g":"ai","word":"Subagent","text":"A helper AI that a main AI hands a smaller job to, and gets the result back from.","also":["subagents","sub-agent"]},{"id":"multiagent","g":"ai","word":"Multi-agent","text":"Several AIs working together on one piece of work, each with its own part, like a small team.","also":["multi-agent system"]},{"id":"autonomy","g":"ai","word":"Autonomy","text":"How much an AI may do on its own before it has to ask a person.","also":["autonomous"]},{"id":"hitl","g":"ai","word":"Human in the loop","text":"Keeping a person involved to check or approve what the AI does at key points. In AI-gile that is you.","also":["human-in-the-loop","HITL"]},{"id":"guardrails","g":"ai","word":"Guardrails","text":"Limits and checks that keep an AI’s actions safe, like needing approval before anything goes live. They lower the risk of mistakes, but don’t rule them out.","also":["guardrail"]},{"id":"rag","g":"ai","word":"Retrieval-augmented generation (RAG)","text":"Letting an AI look things up in your own documents before it answers, so its answers rest on your facts.","also":["RAG","retrieval augmented generation"]},{"id":"embedding","g":"ai","word":"Embedding","text":"Turning text into a list of numbers that captures its meaning, so a computer can find things that mean similar things.","also":["embeddings"]},{"id":"vectordb","g":"ai","word":"Vector database","text":"A database built to search those lists of numbers (embeddings), to find material with a similar meaning.","also":["vector databases","vector store"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"A common way to plug tools and data sources into AI apps, so an AI can use them.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Temperature","text":"A setting for how adventurous an AI’s answers are. Low gives steadier, more predictable answers; high gives more varied ones. Neither makes it always right.","also":["model temperature"],"noTip":1},{"id":"multimodal","g":"ai","word":"Multimodal","text":"Able to work with more than one kind of information, such as text, pictures and sound.","also":["multi-modal"]},{"id":"evals","g":"ai","word":"Evaluation (eval)","text":"A planned test of how well an AI does on chosen examples, so you can compare models or prompts.","also":["eval","evals"]},{"id":"bias","g":"ai","word":"Bias","text":"When an AI (or a person) leans unfairly one way, often because of what it learned from.","also":["biased"],"noTip":1},{"id":"responsible","g":"ai","word":"Responsible AI","text":"Using AI fairly, safely and honestly, with people still answerable for the results.","also":["ethical AI"]},{"id":"injection","g":"ai","word":"Prompt injection","text":"A trick where hidden instructions in a web page or file try to make an AI do something its user didn’t ask for.","also":["prompt injections"]},{"id":"ratelimit","g":"ai","word":"Rate limit","text":"A cap on how many requests you may send to a service in a set time. Go over it and you have to wait.","also":["rate limits","rate limited"]},{"id":"usagelimit","g":"ai","word":"Usage limit","text":"How much AI work your plan allows in a period, after which it pauses or costs more.","also":["usage limits"]},{"id":"vibe","g":"ai","word":"Vibe coding","text":"Building software mostly by describing what you want to an AI and letting it write the code.","also":["vibe-coding"]},{"id":"budget","g":"money","word":"Budget","text":"The amount of money set aside for something.","also":["budgets"],"noTip":1},{"id":"costest","g":"money","word":"Cost estimate","text":"A best guess at what something will cost before you start.","also":["cost estimates"]},{"id":"roi","g":"money","word":"Return on investment (ROI)","text":"What you get back compared with what you put in. If it is positive, it was worth it.","also":["ROI"]},{"id":"tco","g":"money","word":"Total cost of ownership (TCO)","text":"Everything something really costs over its whole life, not just the price to buy it: running, support, upgrades and finally retiring it.","also":["TCO"]},{"id":"capex","g":"money","word":"CapEx and OpEx","text":"CapEx is money spent up front on things you keep; OpEx is ongoing spending, like monthly bills.","also":["CapEx","OpEx","capital expenditure","operating expenditure"]},{"id":"subscription","g":"money","word":"Subscription","text":"Paying regularly, usually monthly or yearly, to keep using something.","also":["subscriptions"],"noTip":1},{"id":"saas","g":"money","word":"Software as a service (SaaS)","text":"Software you use online and pay for by subscription, while the maker runs it for you.","also":["SaaS"]},{"id":"payg","g":"money","word":"Pay as you go","text":"Paying only for what you use, like cloud computing or AI tokens.","also":["pay-as-you-go","usage-based pricing"]},{"id":"overage","g":"money","word":"Overage","text":"Use above what your plan includes, which can cost extra.","also":["overages","overage charges"]},{"id":"billingalert","g":"money","word":"Billing alert","text":"A message when spending or use reaches a level you chose. It warns you, but doesn’t always stop further charges.","also":["billing alerts","spending alert"]},{"id":"freetier","g":"money","word":"Free tier","text":"A free level of a paid service, with limits. Handy for starting out.","also":["free plan"]},{"id":"pricing","g":"money","word":"Pricing plan","text":"The different packages a service sells, each with its own price and limits.","also":["pricing plans","price plan"]},{"id":"licence","g":"money","word":"Licence","text":"The rules for how you may use, copy, change or share something someone else made, such as software, fonts or pictures.","also":["licences","license","licenses"],"noTip":1},{"id":"opensource","g":"money","word":"Open source","text":"Software whose code anyone can read, use and often change for free, under the rules of its licence.","also":["open-source","open source software","OSS"]},{"id":"osslicence","g":"money","word":"Open source licence","text":"The rules that come with open source code. Some let you do almost anything (like MIT); some ask you to share your changes too (like GPL).","also":["open source licences","MIT licence","GPL"]},{"id":"proprietary","g":"money","word":"Proprietary","text":"Owned by a company and not free to copy or change. The opposite of open source.","also":["proprietary software"]},{"id":"copyright","g":"money","word":"Copyright","text":"The legal right of a creator to control copies of their work, including code and writing.","also":["copyrighted"],"noTip":1},{"id":"ip","g":"money","word":"Intellectual property (IP)","text":"Ideas and creations the law treats as owned, like code, designs, names and logos.","also":["intellectual property"]},{"id":"tos","g":"money","word":"Terms of service","text":"The rules you agree to when you use a service.","also":["terms and conditions","terms of use"]},{"id":"contract","g":"money","word":"Contract","text":"A written agreement between two sides that the law will back up.","also":["contracts"],"noTip":1},{"id":"sow","g":"money","word":"Statement of work (SOW)","text":"A document setting out exactly what work will be done, by when and for how much.","also":["SOW"]},{"id":"fixedprice","g":"money","word":"Fixed price","text":"An agreed price for the whole job, however long it takes.","also":["fixed-price"]},{"id":"tm","g":"money","word":"Time and materials","text":"Paying for the hours really worked and the things really used, rather than a set price.","also":["T&M"]},{"id":"invoice","g":"money","word":"Invoice","text":"A bill asking for payment for work done or goods supplied.","also":["invoices"],"noTip":1},{"id":"lockin","g":"money","word":"Vendor lock-in","text":"When moving away from a supplier is so hard or costly that you are stuck with them.","also":["lock-in"]},{"id":"procurement","g":"money","word":"Procurement","text":"The process of choosing and buying from suppliers."},{"id":"servicecredit","g":"money","word":"Service credit","text":"Money back or a discount you get when a supplier misses its SLA.","also":["service credits"]}]}};
